package main
import("crypto/ed25519";"crypto/rand")
func edKey()(ed25519.PublicKey,ed25519.PrivateKey,error){return ed25519.GenerateKey(rand.Reader)}
const page = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZeroLink</title><style>
*{box-sizing:border-box}body{font:15px system-ui;background:#101720;color:#edf3f8;margin:0}main{max-width:1000px;margin:auto;padding:24px;display:grid;grid-template-columns:300px 1fr;gap:20px}header{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between}h1{font-size:26px;margin:0}small{color:#a9bbcc}.panel{background:#192431;border:1px solid #2e4154;border-radius:18px;padding:20px}label{display:block;margin:16px 0 4px;color:#9fbbce;font-size:12px}input,textarea{width:100%;background:#111b26;color:white;border:1px solid #354a60;border-radius:8px;padding:10px;font:inherit}button{background:#75e2b4;color:#09281e;border:0;border-radius:10px;padding:11px 15px;font-weight:700;cursor:pointer}a{color:#9de5ff}#chat{height:56vh;overflow:auto;display:flex;flex-direction:column;gap:12px}.msg{padding:12px 15px;border-radius:14px;background:#253749;max-width:90%;overflow-wrap:anywhere;white-space:pre-wrap;align-self:flex-start}.mine{background:#1c5047;align-self:flex-end}.meta{display:block;color:#b4c9ce;font-size:11px;margin-top:6px}.row{display:flex;gap:8px;align-items:center;margin-top:12px}.row textarea{flex:1;resize:vertical}#status{color:#75e2b4}@media(max-width:700px){main{grid-template-columns:1fr}header{grid-column:1}#chat{height:45vh}}
</style><main><header><div><h1>ZeroLink.</h1><small>Your private space, offline.</small></div><span id="status">Receiver ready</span></header><aside class="panel"><h2>Pair your phone</h2><small>Connect Windows to the phone hotspot. Enter the pairing key and fingerprint once. Laptop IP is optional; automatic discovery runs after pairing. Keep the key private.</small><label>Local IP (fallback)</label><input id="ip" readonly><label>Pairing key</label><input id="token" readonly><label>Certificate fingerprint</label><input id="fp" readonly><button id="copy" style="margin-top:12px">Copy pairing details</button><label>Auto-save destination</label><small id="folder"></small><p><small>Keep the receiver process running. Closing this browser tab does not stop transfers.</small></p></aside><section class="panel"><h2>My phone</h2><div id="chat" aria-live="polite"></div><form class="row"><textarea id="message" placeholder="Send a message to your phone…" required maxlength="30000"></textarea><button>Send</button></form></section></main><script>
const $=id=>document.getElementById(id);let last="";async function api(p,opt){let r=await fetch(p,opt);if(!r.ok)throw Error(await r.text());return r.json()}
async function info(){let i=await api("info");$("ip").value=i.ips.join(", ");$("token").value=i.token;$("fp").value=i.fingerprint;$("folder").textContent=i.folder}
$("copy").onclick=()=>navigator.clipboard.writeText($("ip").value+"\n"+$("token").value+"\n"+$("fp").value).catch(()=>alert("Select and copy the values manually."));
async function refresh(){try{let a=await api("history");let sig=JSON.stringify(a);if(sig===last)return;last=sig;let el=$("chat"),near=el.scrollHeight-el.scrollTop-el.clientHeight<100;el.replaceChildren();for(let x of a){let m=document.createElement("div");m.className="msg"+(x.from==="desktop"?" mine":"");if(x.kind==="file"){let l=document.createElement("a");l.href="download?id="+encodeURIComponent(x.id);l.textContent=x.name;l.download=x.name;m.append(l,document.createTextNode(" • "+x.size+" bytes • saved"));}else m.textContent=x.text;let t=document.createElement("span");t.className="meta";t.textContent=x.from+" · "+new Date(x.time).toLocaleString();m.append(t);el.append(m)}if(near)el.scrollTop=el.scrollHeight;$("status").textContent="Receiver ready"}catch(e){$("status").textContent="Receiver unavailable"}}
document.querySelector("form").onsubmit=async e=>{e.preventDefault();try{await api("message",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text:$("message").value})});$("message").value="";await refresh()}catch(e){alert(e.message)}};info();refresh();setInterval(refresh,3000);
</script></html>`
